#include <cstddef>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <vector>

// Appends every subset of values[from, end) to out, each one combined with the values already chosen.
void collect(std::span<const int> values, std::ptrdiff_t from, std::vector<int>& chosen,
             std::vector<std::vector<int>>& out) {
  if (from == std::ssize(values)) {  // every value has been decided
    out.push_back(chosen);
    return;
  }
  chosen.push_back(values[from]);          // choose values[from]
  collect(values, from + 1, chosen, out);  // explore what follows that choice
  chosen.pop_back();                       // un-choose, so the next branch starts clean
  collect(values, from + 1, chosen, out);  // explore the branch that leaves it out
}

[[nodiscard]] std::vector<std::vector<int>> subsets(std::span<const int> values) {
  std::vector<std::vector<int>> out;
  std::vector<int> chosen;
  chosen.reserve(values.size());
  collect(values, 0, chosen, out);
  return out;
}

[[nodiscard]] std::string show(std::span<const int> subset) {
  std::string out;
  for (const int v : subset) out += std::format("{}{}", out.empty() ? "" : " ", v);
  return "{" + out + "}";
}

int main() {
  const std::vector<int> three{1, 2, 3};
  std::string line;
  for (const std::vector<int>& s : subsets(three)) line += std::format("{}{}", line.empty() ? "" : " ", show(s));
  std::cout << line << '\n';
  std::cout << std::format("{} subsets of 3 values, {} of none\n", subsets(three).size(), subsets({}).size());
}

