#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string_view>
#include <vector>

struct Trace {
  std::int64_t calls = 0;
  std::int64_t live = 0;  // frames of this function on the stack right now
  std::int64_t deepest = 0;
};

// Counts one call for as long as it exists, and records the deepest nesting reached.
class Level {
 public:
  explicit Level(Trace& trace) : trace_(trace) {
    ++trace_.calls;
    ++trace_.live;
    trace_.deepest = std::max(trace_.deepest, trace_.live);
  }
  Level(const Level&) = delete;
  Level& operator=(const Level&) = delete;
  ~Level() { --trace_.live; }

 private:
  Trace& trace_;
};

std::int64_t sum_to(std::int64_t n, Trace& trace) {  // one call per level
  const Level level{trace};
  return n <= 0 ? 0 : n + sum_to(n - 1, trace);  // <= rather than ==, for the reason below
}

std::int64_t halvings(std::int64_t n, Trace& trace) {  // one call per level, on half the input
  const Level level{trace};
  return n <= 1 ? 0 : 1 + halvings(n / 2, trace);
}

std::int64_t fib(int n, Trace& trace) {  // two calls per level
  const Level level{trace};
  return n < 2 ? n : fib(n - 1, trace) + fib(n - 2, trace);
}

std::int64_t subsets(std::span<const int> values, std::ptrdiff_t from, Trace& trace) {  // take it or leave it
  const Level level{trace};
  if (from == std::ssize(values)) return 1;
  return subsets(values, from + 1, trace) + subsets(values, from + 1, trace);
}

void row(std::string_view shape, std::int64_t answer, const Trace& trace) {
  std::cout << std::format("{:<26}{:>10}{:>12}{:>8}\n", shape, answer, trace.calls, trace.deepest);
}

int main() {
  std::cout << std::format("{:<26}{:>10}{:>12}{:>8}\n", "shape", "answer", "calls", "depth");
  Trace linear;
  row("sum_to(20)", sum_to(20, linear), linear);
  Trace halved;
  row("halvings(1048576)", halvings(1'048'576, halved), halved);
  Trace tree;
  row("fib(20)", fib(20, tree), tree);
  Trace branching;
  const std::vector<int> twenty(20, 0);
  row("subsets of 20 values", subsets(twenty, 0, branching), branching);
}

