#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <string>
#include <string_view>
#include <vector>

struct Check {
  std::string name;
  std::int64_t seconds = 0;
};

struct Search {
  explicit Search(std::span<const Check> all) : checks(all) {}

  std::span<const Check> checks;
  std::vector<std::string_view> taken;  // the checks chosen on the path to here
  std::vector<std::string> found;       // one entry per set that fills the budget exactly
  std::int64_t calls = 0;
};

[[nodiscard]] std::string path_of(std::span<const std::string_view> names) {
  std::string out;
  for (const std::string_view name : names) out += std::format("{}{}", out.empty() ? "" : "+", name);
  return out.empty() ? "(none)" : out;
}

// Finds every set of checks[from, end) whose durations add up to exactly `left` seconds.
// prune(left) says whether a branch can be dropped; report(from, taken, left, note) logs one call.
// The reporter gets the chosen names rather than a built path: the silent run below makes 131,071
// calls, and building a string for each would cost more than the search it measures.
template <typename Prune, typename Report>
void explore(Search& search, std::ptrdiff_t from, std::int64_t left, Prune prune, Report report) {
  ++search.calls;
  if (prune(left)) {
    report(from, search.taken, left, "over budget");
    return;
  }
  if (from == std::ssize(search.checks)) {
    const bool exact = left == 0;
    if (exact) search.found.push_back(path_of(search.taken));
    report(from, search.taken, left, exact ? "fills the budget" : "short");
    return;
  }
  report(from, search.taken, left, "");
  const Check& check = search.checks[from];
  search.taken.push_back(check.name);                              // choose
  explore(search, from + 1, left - check.seconds, prune, report);  // explore
  search.taken.pop_back();                                         // un-choose
  explore(search, from + 1, left, prune, report);                  // the branch that skips it
}

int main() {
  const auto over_budget = [](std::int64_t left) { return left < 0; };
  const std::vector<Check> three{{"lidar", 3}, {"imu", 2}, {"odom", 2}};
  Search traced{three};
  explore(traced, 0, 5, over_budget,
          [](std::ptrdiff_t from, std::span<const std::string_view> taken, std::int64_t left,
             std::string_view note) {
            const std::string tail = note.empty() ? "" : std::format("  {}", note);
            std::cout << std::format("{:{}}{:<16}{:>3} s left{}\n", "", 2 * from, path_of(taken), left, tail);
          });
  std::cout << std::format("{} calls, {} sets fill 5 s exactly\n", traced.calls, traced.found.size());

  std::vector<Check> sixteen;
  for (int i = 0; i < 16; ++i) sixteen.push_back({.name = std::format("c{}", i), .seconds = 3 + i});
  const auto never = [](std::int64_t) { return false; };
  const auto silent = [](std::ptrdiff_t, std::span<const std::string_view>, std::int64_t, std::string_view) {};
  Search pruned{sixteen};
  explore(pruned, 0, 20, over_budget, silent);
  Search everything{sixteen};
  explore(everything, 0, 20, never, silent);
  std::cout << std::format("16 checks, budget 20 s: {} sets, {} calls with the cut, {} without\n",
                           pruned.found.size(), pruned.calls, everything.calls);
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <span>
#include <string>
#include <vector>

struct Builder {
  std::span<const int> values;
  std::vector<char> used;   // used[i] is 1 while values[i] sits on the current path
  std::vector<int> chosen;  // the path built so far
  std::vector<std::vector<int>> out;
};

void extend(Builder& b) {
  if (std::ssize(b.chosen) == std::ssize(b.values)) {  // every position is filled
    b.out.push_back(b.chosen);
    return;
  }
  for (std::ptrdiff_t i = 0; i < std::ssize(b.values); ++i) {
    if (b.used[static_cast<std::size_t>(i)] != 0) continue;
    b.used[static_cast<std::size_t>(i)] = 1;  // choose values[i] for this position
    b.chosen.push_back(b.values[i]);
    extend(b);                                // explore
    b.chosen.pop_back();                      // un-choose
    b.used[static_cast<std::size_t>(i)] = 0;
  }
}

[[nodiscard]] std::vector<std::vector<int>> permutations(std::span<const int> values) {
  Builder b{.values = values, .used = std::vector<char>(values.size(), 0), .chosen = {}, .out = {}};
  b.chosen.reserve(values.size());
  extend(b);
  return b.out;
}

[[nodiscard]] std::string show(std::span<const int> row) {
  std::string out;
  for (const int v : row) out += std::format("{}", v);
  return out;
}

int main() {
  const std::vector<int> three{1, 2, 3};
  std::string line;
  for (const std::vector<int>& p : permutations(three)) line += std::format("{}{}", line.empty() ? "" : " ", show(p));
  std::cout << line << '\n';
  std::cout << std::format("one value: {}, no values: {} (the empty permutation)\n",
                           permutations(std::vector<int>{5}).size(), permutations({}).size());

  std::vector<int> eight(8);
  std::iota(eight.begin(), eight.end(), 1);
  const std::vector<std::vector<int>> all = permutations(eight);
  std::vector<std::vector<int>> expected;
  std::vector<int> rolling = eight;
  do {
    expected.push_back(rolling);
  } while (std::ranges::next_permutation(rolling).found);
  std::cout << std::format("8 values: {} permutations, same as next_permutation: {}\n", all.size(), all == expected);
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <string>
#include <vector>

struct Gen {
  std::string current;
  std::vector<std::string> out;
  std::int64_t calls = 0;
};

// open: brackets that may still be opened. unclosed: brackets opened and waiting for their ')'.
void build(Gen& g, std::int64_t open, std::int64_t unclosed) {
  ++g.calls;
  if (open == 0 && unclosed == 0) {  // nothing left to place and nothing left open
    g.out.push_back(g.current);
    return;
  }
  if (open > 0) {
    g.current.push_back('(');  // choose
    build(g, open - 1, unclosed + 1);
    g.current.pop_back();      // un-choose
  }
  if (unclosed > 0) {
    g.current.push_back(')');
    build(g, open, unclosed - 1);
    g.current.pop_back();
  }
}

[[nodiscard]] Gen generate(std::int64_t pairs) {
  Gen g;
  g.current.reserve(static_cast<std::size_t>(2 * pairs));
  build(g, pairs, 0);
  return g;
}

int main() {
  for (const std::int64_t n : {0, 1, 2, 3, 4}) {
    const Gen g = generate(n);
    std::string joined;
    for (const std::string& s : g.out)
      joined += std::format("{}{}", joined.empty() ? "" : " ", s.empty() ? "\"\"" : s);
    std::cout << std::format("n = {}: {:>2} strings  {}\n", n, g.out.size(), joined);
  }
  const Gen eight = generate(8);
  std::cout << std::format("n = 8: {} strings from {} calls\n", eight.out.size(), eight.calls);
}

#include <algorithm>
#include <cstddef>
#include <format>
#include <iostream>
#include <set>
#include <span>
#include <string>
#include <vector>

struct Builder {
  std::span<const int> values;
  std::vector<char> used;
  std::vector<int> chosen;
  std::vector<std::vector<int>> out;
};

void extend_all(Builder& b) {
  if (std::ssize(b.chosen) == std::ssize(b.values)) {
    b.out.push_back(b.chosen);
    return;
  }
  for (std::ptrdiff_t i = 0; i < std::ssize(b.values); ++i) {
    if (b.used[static_cast<std::size_t>(i)] != 0) continue;
    b.used[static_cast<std::size_t>(i)] = 1;
    b.chosen.push_back(b.values[i]);
    extend_all(b);
    b.chosen.pop_back();
    b.used[static_cast<std::size_t>(i)] = 0;
  }
}

void extend_distinct(Builder& b) {
  if (std::ssize(b.chosen) == std::ssize(b.values)) {
    b.out.push_back(b.chosen);
    return;
  }
  for (std::ptrdiff_t i = 0; i < std::ssize(b.values); ++i) {
    if (b.used[static_cast<std::size_t>(i)] != 0) continue;
    // Among equal values, only the leftmost unused one may start a branch.
    if (i > 0 && b.values[i] == b.values[i - 1] && b.used[static_cast<std::size_t>(i - 1)] == 0) continue;
    b.used[static_cast<std::size_t>(i)] = 1;
    b.chosen.push_back(b.values[i]);
    extend_distinct(b);
    b.chosen.pop_back();
    b.used[static_cast<std::size_t>(i)] = 0;
  }
}

template <typename Extend>
[[nodiscard]] std::vector<std::vector<int>> permutations(std::vector<int> values, Extend extend) {
  std::ranges::sort(values);  // equal values end up next to each other
  Builder b{.values = values, .used = std::vector<char>(values.size(), 0), .chosen = {}, .out = {}};
  extend(b);
  return b.out;
}

[[nodiscard]] std::string show(std::span<const std::vector<int>> rows) {
  std::string out;
  for (const std::vector<int>& row : rows) {
    out += out.empty() ? "" : " ";
    for (const int v : row) out += std::format("{}", v);
  }
  return out;
}

int main() {
  for (const std::vector<int>& input : {std::vector{1, 1, 2}, std::vector{1, 1, 2, 2}}) {
    const std::vector<std::vector<int>> all = permutations(input, extend_all);
    const std::vector<std::vector<int>> distinct = permutations(input, extend_distinct);
    const std::set<std::vector<int>> unique(all.begin(), all.end());
    std::cout << std::format("{} values: {} rows, {} distinct, the skip rule gives {}\n", input.size(), all.size(),
                             unique.size(), distinct.size());
  }
  std::cout << show(permutations({1, 1, 2}, extend_all)) << '\n';
  std::cout << show(permutations({1, 1, 2}, extend_distinct)) << '\n';
}

#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <span>
#include <vector>

// The length of a logged path, one frame per segment.
[[nodiscard]] std::int64_t total_mm(std::span<const std::int64_t> segments, std::ptrdiff_t from) {
  if (from == std::ssize(segments)) return 0;
  return segments[from] + total_mm(segments, from + 1);
}

int main() {
  const std::vector<std::int64_t> segments(1'000'000, 3);
  std::cout << std::format("path length {} mm\n", total_mm(segments, 0));
}

#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <format>
#include <iostream>
#include <numeric>
#include <optional>
#include <span>
#include <string>
#include <vector>

struct Check {
  std::string name;
  std::int64_t seconds = 0;
};

struct Frame {
  std::ptrdiff_t from = 0;              // the next check to decide
  std::int64_t left = 0;                // seconds still to fill
  std::ptrdiff_t path_size = 0;         // how long the path was at the parent
  std::optional<std::ptrdiff_t> taken;  // the check appended on the way into this node, if any
};

struct Walk {
  std::vector<std::string> found;
  std::ptrdiff_t deepest = 0;  // the most frames the stack ever held
};

[[nodiscard]] Walk fill_budget(std::span<const Check> checks, std::int64_t budget) {
  Walk walk;
  std::vector<Frame> stack{Frame{.from = 0, .left = budget, .path_size = 0, .taken = std::nullopt}};
  std::vector<std::ptrdiff_t> path;  // indices chosen on the way to the current node
  while (!stack.empty()) {
    const Frame frame = stack.back();
    stack.pop_back();
    path.resize(static_cast<std::size_t>(frame.path_size));  // back out of the branch just finished
    if (frame.taken) path.push_back(*frame.taken);           // and into this one
    if (frame.left < 0) continue;
    if (frame.from == std::ssize(checks)) {
      if (frame.left == 0) {
        std::string names;
        for (const std::ptrdiff_t i : path) names += std::format("{}{}", names.empty() ? "" : "+", checks[i].name);
        walk.found.push_back(names);
      }
      continue;
    }
    const std::ptrdiff_t size = std::ssize(path);
    stack.push_back({.from = frame.from + 1, .left = frame.left, .path_size = size, .taken = std::nullopt});
    stack.push_back({.from = frame.from + 1,
                     .left = frame.left - checks[frame.from].seconds,
                     .path_size = size,
                     .taken = frame.from});
    walk.deepest = std::max(walk.deepest, std::ssize(stack));
  }
  return walk;
}

int main() {
  const std::vector<std::int64_t> segments(1'000'000, 3);
  std::cout << std::format("path length {} mm, no recursion\n",
                           std::accumulate(segments.begin(), segments.end(), std::int64_t{0}));

  std::vector<Check> sixteen;
  for (int i = 0; i < 16; ++i) sixteen.push_back({.name = std::format("c{}", i), .seconds = 3 + i});
  const Walk walk = fill_budget(sixteen, 20);
  std::cout << std::format("{} sets fill 20 s, deepest stack {} frames, first set {}\n", walk.found.size(),
                           walk.deepest, walk.found.front());
}
